#include <cstdio>
typedef long long ll;

ll cross(ll ux, ll uy, ll vx, ll vy, ll wx, ll wy) { return (vx - ux) * (wy - uy) - (vy - uy) * (wx - ux); }

ll x1, y1_, x2, y2, x3, y3;

// Inside or on the boundary: the three edge cross products never have both signs.
bool inside(ll px, ll py) {
    ll z[3] = {cross(x1, y1_, x2, y2, px, py), cross(x2, y2, x3, y3, px, py), cross(x3, y3, x1, y1_, px, py)};
    bool neg = false, pos = false;
    for (ll v : z) { if (v < 0) neg = true; if (v > 0) pos = true; }
    return !(neg && pos);
}

int main() {
    ll xp, yp, xq, yq;
    if (scanf("%lld %lld %lld %lld %lld %lld %lld %lld %lld %lld", &x1, &y1_, &x2, &y2, &x3, &y3, &xp, &yp, &xq, &yq) != 10) return 0;
    if (cross(x1, y1_, x2, y2, x3, y3) == 0) { puts("0"); return 0; }  // degenerate triangle
    bool p = inside(xp, yp), q = inside(xq, yq);
    printf("%d\n", p && q ? 3 : p ? 1 : q ? 2 : 4);
}

