package main

import "fmt"

type pt struct{ x, y int64 }

func cross(u, v, w pt) int64 { return (v.x-u.x)*(w.y-u.y) - (v.y-u.y)*(w.x-u.x) }

func main() {
	var a, b, c, p, q pt
	fmt.Scan(&a.x, &a.y, &b.x, &b.y, &c.x, &c.y, &p.x, &p.y, &q.x, &q.y)
	if cross(a, b, c) == 0 { // degenerate triangle
		fmt.Println(0)
		return
	}
	// Inside or on the boundary: the three edge cross products never have both signs.
	inside := func(r pt) bool {
		neg, pos := false, false
		for _, v := range []int64{cross(a, b, r), cross(b, c, r), cross(c, a, r)} {
			if v < 0 {
				neg = true
			}
			if v > 0 {
				pos = true
			}
		}
		return !(neg && pos)
	}
	ip, iq := inside(p), inside(q)
	switch {
	case ip && iq:
		fmt.Println(3)
	case ip:
		fmt.Println(1)
	case iq:
		fmt.Println(2)
	default:
		fmt.Println(4)
	}
}
